from collections import deque

class NetworkSimplex:
    def __init__(self, n, arc_tuples, initial_flow):
        self.n=n
        self.fr=[]; self.to=[]; self.lo=[]; self.hi=[]; self.cost=[]; self.flow=[]; self.basic=[]
        for (u,v,l,h,c),f in zip(arc_tuples,initial_flow):
            if not (0<=u<n and 0<=v<n and 0<=l<=f<=h):
                raise ValueError(('bad arc',u,v,l,h,f))
            eid=len(self.fr)
            self.fr.append(u);self.to.append(v);self.lo.append(l);self.hi.append(h);self.cost.append(c)
            self.flow.append(f);self.basic.append(0)
        self.E=len(self.fr)
        self.tadj=[[] for _ in range(n)]
        self.iters=0;self.bound_flips=0;self.degenerate=0
        self._make_basis()
        self.max_iters=2000000

    def _make_basis(self):
        n=self.n; fr=self.fr;to=self.to;lo=self.lo;hi=self.hi;flow=self.flow
        inside=[lo[i]<flow[i]<hi[i] for i in range(self.E)]
        # remove cycles in interior support by flow adjustment
        rounds=0
        while True:
            adj=[[] for _ in range(n)]
            anyint=False
            for i in range(self.E):
                if inside[i]:
                    anyint=True; u=fr[i];v=to[i]; adj[u].append(i);adj[v].append(i)
            if not anyint: break
            par=[-2]*n; pare=[-1]*n; cyc=None
            for st in range(n):
                if par[st]!=-2: continue
                par[st]=-1; stack=[(st,0)]
                while stack:
                    u,idx=stack[-1]
                    if idx>=len(adj[u]):
                        stack.pop(); continue
                    eid=adj[u][idx]; stack[-1]=(u,idx+1)
                    a=fr[eid];b=to[eid]; v=b if a==u else a
                    if v==par[u]: continue
                    if par[v]==-2:
                        par[v]=u; pare[v]=eid; stack.append((v,0))
                    else:
                        # cycle u -> ... parent ... v, then eid v->u
                        # Build path u up to v (v should be ancestor)
                        ue=[]; cur=u
                        # guard
                        while cur!=v:
                            if cur<0 or pare[cur]<0: raise RuntimeError('cycle ancestor fail')
                            ue.append(pare[cur]); cur=par[cur]
                        # traversal: from u upward along ue, then closing eid v->u
                        cur=u; theta=None
                        for ee in ue:
                            a1=fr[ee];b1=to[ee]
                            forward=(a1==cur)
                            nxt=b1 if forward else a1
                            res=(hi[ee]-flow[ee]) if forward else (flow[ee]-lo[ee])
                            if res<=0: raise RuntimeError('interior res zero')
                            if theta is None or res<theta: theta=res
                            cur=nxt
                        # closing traversal v->u
                        a1=fr[eid];b1=to[eid]
                        forward=(a1==cur)  # cur should v
                        res=(hi[eid]-flow[eid]) if forward else (flow[eid]-lo[eid])
                        if res<=0: raise RuntimeError('closing res zero')
                        if theta is None or res<theta: theta=res
                        # apply
                        cur=u
                        for ee in ue:
                            a1=fr[ee];b1=to[ee]
                            forward=(a1==cur); nxt=b1 if forward else a1
                            flow[ee] += theta if forward else -theta
                            cur=nxt
                        flow[eid] += theta if forward else -theta
                        cyc=True
                        break
                if cyc: break
            if not cyc:
                raise RuntimeError('cycle found none though interior exists')
            # update inside
            for i in range(self.E):
                if inside[i] and not (lo[i]<flow[i]<hi[i]): inside[i]=False
            rounds+=1
            if rounds>self.E+5: raise RuntimeError('cycle rounds')
        # Build spanning tree, interior first
        parent=list(range(n)); rank=[0]*n
        def find(x):
            while parent[x]!=x:
                parent[x]=parent[parent[x]];x=parent[x]
            return x
        def union(a,b):
            ra=find(a);rb=find(b)
            if ra==rb:return False
            if rank[ra]<rank[rb]:ra,rb=rb,ra
            parent[rb]=ra
            if rank[ra]==rank[rb]:rank[ra]+=1
            return True
        tree=[]
        for i in range(self.E):
            if lo[i]<flow[i]<hi[i]:
                if not union(fr[i],to[i]): raise RuntimeError('interior still cycle')
                tree.append(i)
        # all others
        for i in range(self.E):
            if not (lo[i]<flow[i]<hi[i]):
                if union(fr[i],to[i]): tree.append(i)
        if len(tree)!=n-1:
            # graph disconnected; add fixed artificial connectors via root? fallback raise
            raise RuntimeError(('not connected',n,len(tree)))
        for eid in tree:
            self.basic[eid]=1
            self.tadj[fr[eid]].append(eid);self.tadj[to[eid]].append(eid)

    def potentials(self):
        n=self.n; pi=[None]*n; pi[0]=0; dq=deque([0])
        while dq:
            u=dq.popleft();pu=pi[u]
            for eid in self.tadj[u]:
                a=self.fr[eid];b=self.to[eid]
                if a==u:
                    if pi[b] is None: pi[b]=pu+self.cost[eid];dq.append(b)
                elif b==u:
                    if pi[a] is None: pi[a]=pu-self.cost[eid];dq.append(a)
                else: raise RuntimeError('bad tree')
        if any(x is None for x in pi): raise RuntimeError('tree disconnected')
        return pi

    def find_path(self,start,target):
        n=self.n; par=[-2]*n;pare=[-1]*n
        par[start]=-1;dq=deque([start])
        while dq:
            u=dq.popleft()
            if u==target:break
            for eid in self.tadj[u]:
                a=self.fr[eid];b=self.to[eid]; v=b if a==u else a
                if par[v]==-2:
                    par[v]=u;pare[v]=eid;dq.append(v)
        if par[target]==-2:raise RuntimeError('no path')
        path=[];cur=target
        while cur!=start:
            path.append(pare[cur]);cur=par[cur]
        path.reverse();return path

    def solve(self, verbose=False):
        n=self.n; E=self.E
        while True:
            self.iters+=1
            if self.iters>self.max_iters: raise RuntimeError('iteration limit')
            pi=self.potentials()
            enter=-1;alpha=0
            # Bland smallest index
            for eid in range(E):
                if self.basic[eid]:continue
                l=self.lo[eid];h=self.hi[eid]
                if h<=l:continue
                x=self.flow[eid];rc=self.cost[eid]+pi[self.fr[eid]]-pi[self.to[eid]]
                if x==l:
                    if rc<0:enter=eid;alpha=1;break
                elif x==h:
                    if rc>0:enter=eid;alpha=-1;break
                else:
                    raise RuntimeError(('nonbasic interior',eid,x,l,h))
            if enter<0:return True
            u=self.fr[enter];v=self.to[enter]
            # cycle return path opposite entering traversal
            start,end=(v,u) if alpha==1 else (u,v)
            path=self.find_path(start,end)
            enter_res=(self.hi[enter]-self.flow[enter]) if alpha==1 else (self.flow[enter]-self.lo[enter])
            theta=enter_res;leave=-1
            cur=start;dirs=[]
            for eid in path:
                a=self.fr[eid];b=self.to[eid]
                if a==cur: forward=True;nxt=b
                elif b==cur: forward=False;nxt=a
                else: raise RuntimeError('path dir')
                res=(self.hi[eid]-self.flow[eid]) if forward else (self.flow[eid]-self.lo[eid])
                dirs.append(forward)
                if res<theta:
                    theta=res;leave=eid
                elif res==theta:
                    if leave<0 or eid<leave:leave=eid
                cur=nxt
            if cur!=end:raise RuntimeError('path end')
            if theta<0:raise RuntimeError('theta neg')
            if theta:
                cur=start
                for eid,forward in zip(path,dirs):
                    if forward:self.flow[eid]+=theta
                    else:self.flow[eid]-=theta
                    cur=(self.to[eid] if self.fr[eid]==cur else self.fr[eid])
                self.flow[enter]+=alpha*theta
            else:
                self.degenerate+=1
            if leave>=0:
                self.basic[leave]=0
                a=self.fr[leave];b=self.to[leave]
                try:self.tadj[a].remove(leave)
                except ValueError:pass
                try:self.tadj[b].remove(leave)
                except ValueError:pass
                self.basic[enter]=1
                self.tadj[u].append(enter);self.tadj[v].append(enter)
            else:
                self.bound_flips+=1
            if verbose and self.iters%1000==0:
                import sys;print('iter',self.iters,'enter',enter,'theta',theta,'leave',leave,'degen',self.degenerate,file=sys.stderr)

    def objective(self):
        return sum(self.cost[i]*self.flow[i] for i in range(self.E))
