from ns2 import NetworkSimplex

def brute(n,arcs):
    ranges=[range(l,h+1) for u,v,l,h,c in arcs]
    best=None;bestf=None
    for fs in itertools.product(*ranges):
        bal=[0]*n
        for (u,v,l,h,c),x in zip(arcs,fs):
            bal[u]+=x;bal[v]-=x
        if any(bal):continue
        val=sum(c*x for (_,_,_,_,c),x in zip(arcs,fs))
        if best is None or val<best:best=val;bestf=fs
    return best,bestf
